package in.industrend.identity.auth;
import jakarta.servlet.http.*;import java.time.Duration;import java.util.Map;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.ResponseCookie;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin-auth") public class AdminAuthController{static final String COOKIE="IT_ADMIN_SESSION";record LoginRequest(String email,String password){}private final AdminAuthService auth;private final boolean secure;AdminAuthController(AdminAuthService auth,@Value("${app.security.cookie-secure:true}")boolean secure){this.auth=auth;this.secure=secure;}@PostMapping("/login")Map<String,Object>login(@RequestBody LoginRequest body,HttpServletRequest req,HttpServletResponse res){var result=auth.login(body.email(),body.password(),ip(req),req.getHeader("User-Agent"));cookie(res,result.token(),result.expiresInSeconds());return Map.of("displayName",result.displayName(),"email",result.email(),"csrfToken",result.csrf());}@GetMapping("/session")Map<String,Object>session(@CookieValue(value=COOKIE,required=false)String token){return auth.validate(token);}@PostMapping("/logout")Map<String,Boolean>logout(@CookieValue(value=COOKIE,required=false)String token,HttpServletResponse res){auth.logout(token);cookie(res,"",0);return Map.of("loggedOut",true);}private void cookie(HttpServletResponse res,String value,long ttl){res.addHeader("Set-Cookie",ResponseCookie.from(COOKIE,value).httpOnly(true).secure(secure).sameSite("Strict").path("/").maxAge(Duration.ofSeconds(ttl)).build().toString());}private String ip(HttpServletRequest r){var f=r.getHeader("X-Forwarded-For");return f==null?r.getRemoteAddr():f.split(",")[0].trim();}}
